import{_ as s,o as t,c as a,ag as o}from"./chunks/framework.DNmTgtHf.js";const u=JSON.parse('{"title":"Backpressure","description":"","frontmatter":{},"headers":[],"relativePath":"todo/my_verify_docs/backpressure.md","filePath":"todo/my_verify_docs/backpressure.md"}'),i={name:"todo/my_verify_docs/backpressure.md"};function r(l,e,n,h,d,c){return t(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="backpressure" tabindex="-1">Backpressure <a class="header-anchor" href="#backpressure" aria-label="Permalink to &quot;Backpressure&quot;">​</a></h1><h2 id="in-one-sentence" tabindex="-1">In one sentence <a class="header-anchor" href="#in-one-sentence" aria-label="Permalink to &quot;In one sentence&quot;">​</a></h2><p><strong>Backpressure is the system telling the producer &quot;slow down, I can&#39;t keep up&quot; — instead of silently falling over.</strong></p><h2 id="the-problem-it-solves" tabindex="-1">The problem it solves <a class="header-anchor" href="#the-problem-it-solves" aria-label="Permalink to &quot;The problem it solves&quot;">​</a></h2><p>Imagine a fast producer and a slow consumer:</p><ul><li><strong>Producer:</strong> the HTTP handler, receiving 1000 requests/sec, each wanting to archive something to S3.</li><li><strong>Consumer:</strong> S3 uploads, which maybe finish at 200/sec.</li></ul><p>If you do nothing, the gap (800/sec) has to go <em>somewhere</em>. Three possible outcomes:</p><table tabindex="0"><thead><tr><th>Strategy</th><th>What happens</th></tr></thead><tbody><tr><td>Unbounded queue</td><td>Tasks pile up in memory forever → heap fills → <code>OutOfMemoryError</code> → crash</td></tr><tr><td>Drop silently</td><td>You lose archive data and don&#39;t know it</td></tr><tr><td><strong>Backpressure</strong></td><td>Producer is <em>forced</em> to slow down to match the consumer&#39;s speed</td></tr></tbody></table><p>Backpressure is option 3. It makes the slowness <strong>visible and felt</strong> by whoever is producing work, instead of hiding it in a growing buffer or a silent drop.</p><h2 id="how-apirequestresponsearchiver-does-backpressure" tabindex="-1">How <code>ApiRequestResponseArchiver</code> does backpressure <a class="header-anchor" href="#how-apirequestresponsearchiver-does-backpressure" aria-label="Permalink to &quot;How \`ApiRequestResponseArchiver\` does backpressure&quot;">​</a></h2><p>Look at <code>submitArchiveTask</code>:</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">this</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.writeQueue.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">offer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(archiveTask)) {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // queue had room → fast path, return immediately</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">} </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">else</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  log.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">info</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Queue offer failed ...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  this</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.writeQueue.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">put</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(archiveTask);   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ← THIS is backpressure</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The queue has a <strong>fixed size</strong> (<code>myservice.api.archive.s3.queue.size</code>). When it&#39;s full:</p><ol><li><code>offer()</code> returns <code>false</code> (can&#39;t fit).</li><li><code>put()</code> is called instead. <code>put()</code> <strong>blocks</strong> — the calling thread sits and waits until a worker pulls something off the queue and frees a slot.</li><li>Only then does <code>put()</code> return and the HTTP handler continue.</li></ol><p>The HTTP thread is now <strong>deliberately slowed down</strong> to the exact speed that S3 uploads can drain the queue. That&#39;s backpressure.</p><h2 id="why-this-is-good" tabindex="-1">Why this is good <a class="header-anchor" href="#why-this-is-good" aria-label="Permalink to &quot;Why this is good&quot;">​</a></h2><ul><li><strong>No memory blow-up.</strong> Queue size is capped.</li><li><strong>No silent data loss.</strong> Every task eventually gets processed.</li><li><strong>Slowness propagates honestly.</strong> If S3 is slow, the API gets slow. That&#39;s a signal — dashboards light up, alerts fire, you know there&#39;s a problem. Compare with &quot;S3 is slow but API is fast and we&#39;re silently dropping audit logs&quot; — much worse.</li></ul><h2 id="why-this-is-also-uncomfortable" tabindex="-1">Why this is also uncomfortable <a class="header-anchor" href="#why-this-is-also-uncomfortable" aria-label="Permalink to &quot;Why this is also uncomfortable&quot;">​</a></h2><p>Backpressure means <strong>the slowness travels upstream</strong>. In the archiver:</p><ul><li>S3 slow → archive queue fills</li><li>Queue full → <code>put()</code> blocks the HTTP thread</li><li>HTTP thread blocked → API latency goes up</li><li>API slow → client retries → more load → worse</li></ul><p>So backpressure is a <strong>design choice with teeth</strong>. The code is saying &quot;I&#39;d rather my API slow down than lose archive data.&quot; The alternative would be to drop archive tasks when the queue is full (call <code>offer()</code> and if it fails, log and give up). That keeps the API fast but loses data.</p><p>The current code picked &quot;slow down the API&quot; — which is often the right call for audit/compliance data where losing records is worse than a latency spike.</p><h2 id="why-this-matters-for-the-threadpoolexecutor-refactor" tabindex="-1">Why this matters for the <code>ThreadPoolExecutor</code> refactor <a class="header-anchor" href="#why-this-matters-for-the-threadpoolexecutor-refactor" aria-label="Permalink to &quot;Why this matters for the \`ThreadPoolExecutor\` refactor&quot;">​</a></h2><p><code>ThreadPoolExecutor</code> has several built-in rejection policies for when the queue is full:</p><table tabindex="0"><thead><tr><th>Built-in policy</th><th>Behavior</th><th>Matches current archiver behavior?</th></tr></thead><tbody><tr><td><code>AbortPolicy</code> (default)</td><td>Throw <code>RejectedExecutionException</code></td><td>No — would break callers</td></tr><tr><td><code>DiscardPolicy</code></td><td>Silently drop the task</td><td>No — loses archive data</td></tr><tr><td><code>DiscardOldestPolicy</code></td><td>Drop the oldest queued task</td><td>No — loses archive data</td></tr><tr><td><code>CallerRunsPolicy</code></td><td>Run task on calling thread (HTTP thread!)</td><td>No — HTTP thread would do the slow S3 upload</td></tr></tbody></table><p>None of them match &quot;log + blocking put&quot;. So the refactor needs a small custom <code>RejectedExecutionHandler</code> that does exactly that. Two lines of behavior, preserved exactly.</p><h2 id="backpressure-appears-everywhere" tabindex="-1">Backpressure appears everywhere <a class="header-anchor" href="#backpressure-appears-everywhere" aria-label="Permalink to &quot;Backpressure appears everywhere&quot;">​</a></h2><p>Once you know the word, you see it everywhere:</p><ul><li><strong><code>StageExecutor</code> timeouts</strong> — a form of backpressure: &quot;I can&#39;t wait longer than X, so fail fast.&quot;</li><li><strong>Feign client connection pools</strong> — bounded pools that block when exhausted.</li><li><strong>Database connection pools (HikariCP)</strong> — blocks when all connections are busy.</li><li><strong>Kafka consumers with <code>max.poll.records</code></strong> — bounded fetch size.</li></ul><p>All the same idea: <strong>cap how much work is in flight, and make overflow visible</strong>.</p>`,30)])])}const k=s(i,[["render",r]]);export{u as __pageData,k as default};
